const input = $items('Execute Workflow Trigger', 0, 0)[0].json;
const api = items[0]?.json || {};
const history = api.data || api.client || api;

const now = new Date();
const lastVisitRaw = history.last_visit || history.lastVisit || null;
const lastVisit = lastVisitRaw ? new Date(lastVisitRaw) : null;
const daysSinceLastVisit = lastVisit ? Math.floor((now - lastVisit) / (1000 * 60 * 60 * 24)) : null;

const client = {
  id: history.id || history.client_id || null,
  name: history.name || input.name || '',
  last_service: history.last_service || history.lastService || '',
  last_visit: lastVisitRaw,
  visit_count: history.visit_count || history.visitCount || 0,
  opted_out: Boolean(history.opted_out || history.optedOut)
};

const defaultOfferByService = {
  'Coloracao Global': 'tratamento capilar',
  'Corte Feminino': 'hidratacao',
  'Corte Masculino': 'barba',
  'Barba com Maquina': 'cabelo e barba'
};

const offer = defaultOfferByService[client.last_service] || 'tratamento capilar';
const blocked = Boolean(client.opted_out);
const reason = blocked ? 'opted_out' : null;
const proactiveType = input.proactive_type || 'promotion';

const systemPrompt = `# Vendas e Follow-up - Studio Tirra\nTom amigavel, objetivo e nao insistente.\nRetorne JSON com sales_text.`;

const userPrompt = `Cliente: ${client.name || 'cliente'}\nUltimo servico: ${client.last_service || 'desconhecido'}\nUltima visita: ${client.last_visit || 'desconhecida'}\nDias desde ultima visita: ${daysSinceLastVisit ?? 'desconhecido'}\nFrequencia de visitas: ${client.visit_count || 0}\nOferta recomendada: ${offer}\nTipo de mensagem: ${proactiveType}\nMensagem original: ${input.message || 'cliente pediu informacao comercial'}\n\nRetorne JSON com sales_text.`;

const safePhone = (input.phone || '').replace(/[^0-9]/g, '');
const agentLabel = blocked ? 'sales_blocked_optout' : 'sales';
return [{
  json: {
    ...input,
    phone: safePhone,
    client,
    offer,
    blocked,
    reason,
    agent_label: agentLabel,
    proactive_type: proactiveType,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    llm_provider: ($env.LLM_PROVIDER || 'openai').toLowerCase()
  }
}];

const source = $items('Build Offer', 0, 0)[0].json;
let sales_text = `Oi ${source.client?.name || ''}! Tenho uma sugestao para voce: ${source.offer}. Quer que eu te envie horarios?`;
let text = '';
if ($json.choices?.[0]?.message?.content) text = $json.choices[0].message.content;
if (!text && Array.isArray($json.content) && $json.content[0]?.text) text = $json.content[0].text;

try {
  const parsed = JSON.parse(text);
  if (parsed.sales_text) sales_text = parsed.sales_text;
} catch (e) {}

sales_text = (sales_text || '').replace(/'/g, "''");
return [{ json: { ...source, sales_text } }];
